def test_schema_enableDynamicField_null():
    """Test schema.enableDynamicField=null on collection create"""
    cname = "coll_enable_null_" + uuid.uuid4().hex[:8]

    # Create collection with schema.enableDynamicField=null
    payload = {
        "collectionName": cname,
        "schema": {
            "autoID": False,
            "enableDynamicField": None,  # null
            "fields": [
                {"fieldName": "id", "dataType": "Int64", "isPrimary": True},
                {"fieldName": "vector", "dataType": "FloatVector", "elementTypeParams": {"dim": 4}}
            ]
        },
        "indexParams": [
            {"fieldName": "vector", "metricType": "COSINE", "indexType": "AUTOINDEX"}
        ]
    }

    r = requests.post(f"{BASE_URL}/v2/vectordb/collections/create", 
                      json=payload, headers=get_headers())

    print(f"Response status: {r.status_code}")
    print(f"Response body: {r.text}")

    if r.status_code == 200 and r.json().get('code') == 0:
        print("[DEFECT: ILLEGAL_SUCCESS] Server accepted schema.enableDynamicField=null")
        # Clean up
