                     json={"collectionName": cname}, headers=get_headers())
        return True
    else:
        print("Server properly rejected schema.enableDynamicField=null")
        return False

if __name__ == "__main__":
    defect_found = test_schema_enableDynamicField_null()
    if defect_found:
        sys.exit(1)
    else:
        sys.exit(0)

